def zone_editor_page(config: dict) -> str:
    """Embed already-validated zone data without permitting a script breakout."""
    encoded = json.dumps(config, ensure_ascii=False, allow_nan=False)
    encoded = (encoded.replace('&', r'\u0026').replace('<', r'\u003c')
               .replace('>', r'\u003e').replace('\u2028', r'\u2028').replace('\u2029', r'\u2029'))
    body = EDITOR_BODY.replace('__ZONE_CONFIG__', encoded)
    return _document('C500 Guard · Edit detection zones', body, EDITOR_SCRIPT)
